def run(order):
    x = 1
    for who in order:
        if who == "A":
            x = x * 2
        else:
            x = x + 3
    return x

print(run("AAB"))
print(run("ABA"))
print(run("BAA"))

def count_words(text):
    count = 0
    for ch in text:
        if ch == " ":
            count += 1
    return count + 1

print(count_words("I like cats"))
print(count_words("hello"))
print(count_words(""))
print(count_words("two  spaces"))

