nums = [7, 3, 9, 2, 5]
for i in range(len(nums) - 1):
    small = i
    for j in range(i + 1, len(nums)):
        if nums[j] < nums[small]:
            small = j
    nums[i], nums[small] = nums[small], nums[i]
    print(nums)

queue = ["open"]
log = []

def on_open():
    log.append("open")
    queue.append("load")
    queue.append("draw")

def on_load():
    log.append("load")
    queue.append("save")

def on_draw():
    log.append("draw")

def on_save():
    log.append("save")

handlers = {
    "open": on_open,
    "load": on_load,
    "draw": on_draw,
    "save": on_save
}

while queue:
    event = queue.pop(0)
    handlers[event]()

print(log)

def grade(score):
    if score > 80:
        return "A"
    elif score > 65:
        return "B"
    elif score >= 50:
        return "C"
    return "F"

for s in [80, 65, 64, 50, 49]:
    print(s, grade(s))
